python3 << 'EOF'
import numpy as np
lines = open('optimized.xyz').read().splitlines()
n = int(lines[0])
at = []
for l in lines[2:2+n]:
    p = l.split()
    at.append((p[0], np.array([float(p[1]), float(p[2]), float(p[3])])))
xyz = {i: at[i][1] for i in range(n)}
Ru = xyz[0]
lig = {'N1(py)':1, "C2'(L-carb)":2, "C2''(R-carb)":3, 'CO(down)':4, 'OC(wedge)':6, 'H(hydride)':8}
vecs = {}
for name, i in lig.items():
    v = xyz[i] - Ru
    vecs[name] = v/np.linalg.norm(v)
    print(f'{name:14s} dist={np.linalg.norm(xyz[i]-Ru):.3f}  dir={np.round(vecs[name],3)}')
print('\nAngles between ligands:')
names = list(lig.keys())
for i in range(len(names)):
    for j in range(i+1, len(names)):
        c = np.dot(vecs[names[i]], vecs[names[j]])
        print(f'{names[i]:14s} - {names[j]:14s}: {np.degrees(np.arccos(np.clip(c,-1,1))):6.1f}')
EOF
